exercicios.explicacao_md:
Nas APIs de chat (OpenAI e Anthropic) o histórico é uma **lista de dicts** — cada mensagem tem `role` e `content`:

```python
messages = [
    {"role": "system", "content": "Seja breve."},
    {"role": "user", "content": "Oi!"},
]
messages[1]["content"]   # "Oi!" — indexa a lista, depois lê a chave

# dict-contador: crie a chave com 0 na primeira vez, depois some
contagem = {}
for cor in ["azul", "verde", "azul"]:
    if cor not in contagem:
        contagem[cor] = 0
    contagem[cor] += 1
# {"azul": 2, "verde": 1}
```

Esses dois padrões — navegar dict aninhado e contar com dict — resolvem metade da análise de logs e histórico de chat. Guarde-os.

exercicios.solucao_referencia:
def contar_roles(messages):
    contagem = {}
    for msg in messages:
        role = msg["role"]
        if role not in contagem:
            contagem[role] = 0
        contagem[role] += 1
    return contagem

def ultima_pergunta(messages):
    resultado = ""
    for msg in messages:
        if msg["role"] == "user":
            resultado = msg["content"]
    return resultado

def frequencia(texto):
    contagem = {}
    for palavra in texto.split():
        palavra = palavra.lower()
        if palavra not in contagem:
            contagem[palavra] = 0
        contagem[palavra] += 1
    return contagem

def dedupe(ids):
    vistos = set()
    resultado = []
    for item in ids:
        if item not in vistos:
            vistos.add(item)
            resultado.append(item)
    return resultado

def remontar(perguntas, respostas):
    messages = []
    for pergunta, resposta in zip(perguntas, respostas):
        messages.append({"role": "user", "content": pergunta})
        messages.append({"role": "assistant", "content": resposta})
    return messages

def expurgar_vazias(historico):
    for msg in historico[:]:
        if not msg["content"].strip():
            historico.remove(msg)
    return historico

def tokens_por_modelo(registros):
    totais = {}
    for reg in registros:
        modelo = reg.get("modelo", "desconhecido")
        tokens = reg.get("tokens", 0)
        totais[modelo] = totais.get(modelo, 0) + tokens
    return totais

def pegar_pontuacao(par):
    return par[1]

def ranquear(nomes, pontuacoes):
    pares = list(zip(nomes, pontuacoes))
    ordenados = sorted(pares, key=pegar_pontuacao, reverse=True)
    ranking = []
    for nome, pontuacao in ordenados:
        ranking.append(nome)
    return ranking

def montar_requisicao(prompt, modelo="mock-4", temperatura=0.7, **extras):
    req = {
        "model": modelo,
        "temperature": temperatura,
        "messages": [{"role": "user", "content": prompt}],
    }
    req.update(extras)
    return req

def ordenar_por_custo(modelos):
    ordenados = sorted(modelos, key=lambda m: m["custo_por_1k"])
    nomes = []
    for m in ordenados:
        nomes.append(m["nome"])
    return nomes

def aplicar_em_lote(func, textos):
    resultados = []
    for texto in textos:
        resultados.append(func(texto))
    return resultados

def log_parametros(**params):
    partes = []
    for chave in sorted(params):
        partes.append(f"{chave}={params[chave]}")
    return " ".join(partes)

def registrar(evento, historico=None):
    if historico is None:
        historico = []
    historico.append(evento)
    return historico

def registrar_uso(modelo, *tokens):
    if not tokens:
        raise ValueError("nenhum token informado")
    for t in tokens:
        if not isinstance(t, int):
            raise TypeError(f"token inválido: {t!r}")
    return {"modelo": modelo, "chamadas": len(tokens), "total": sum(tokens)}

